(24561, 'James 2:2', 'James', 2, 2, 'فرض کړئ یو سړی چې د سرو زرو ګوته یې په لاس وي او ښکلي کالي یې اغوستي وي او ستاسو غونډې ته راشي او یو غریب سړی په زړو کالیو کې راشي', 'فرض کری یو سری چې د سرو زرو ګوته یې په لاس وی او شکلی کالی یې اغوستی وی او ستاسو غوندې ته راشی او یو غریب سری په زرو کالیو کې راشی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24562, 'James 2:3', 'James', 2, 3, 'او تاسو د هغه سړي درناوی وکړئ چې ښکلي کالي یې اغوستي دي او ورته ووایئ: «مهرباني وکړئ دلته په دې ښه ځای کې کښېنئ» او هغه غریب سړي ته ووایئ: «هلته ودرېږه یا دلته په ځمکه باندې کښېنه.»', 'او تاسو د هغه سری درناوی وکری چې شکلی کالی یې اغوستی دی او ورته ووایی: «مهربانی وکری دلته په دې شه جای کې کشېنی» او هغه غریب سری ته ووایی: «هلته ودرېزه یا دلته په جمکه باندې کشېنه.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24563, 'James 2:4', 'James', 2, 4, 'ایا تاسو په خپل منځ کې د تبعیض څخه کار وانخیست او ایا د بدو خیالونو له مخې مو قضاوت ونه کړ؟', 'ایا تاسو په خپل منج کې د تبعیض چخه کار وانخیست او ایا د بدو خیالونو له مخې مو قضاوت ونه کر؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24564, 'James 2:5', 'James', 2, 5, 'ای زما ګرانو خویندو او ورونو! واورئ، ایا خدای د دې نړۍ غریبان نه دي غوره کړي چې په ایمان کې شتمن وي او د هغې پاچاهۍ وارثان وي چې خدای د هغو خلکو سره وعده کړې ده چې ورسره مینه کوي؟', 'ای زما ګرانو خویندو او ورونو! واوری، ایا خدای د دې نری غریبان نه دی غوره کری چې په ایمان کې شتمن وی او د هغې پاچاهی وارثان وی چې خدای د هغو خلکو سره وعده کرې ده چې ورسره مینه کوی؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24565, 'James 2:6', 'James', 2, 6, 'خو تاسو د غریب سړي سپکاوی وکړ. ایا شتمن خلک په تاسو باندې ظلم نه کوي او تاسو محکمو ته نه راکاږي؟', 'خو تاسو د غریب سری سپکاوی وکر. ایا شتمن خلک په تاسو باندې ظلم نه کوی او تاسو محکمو ته نه راکازی؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24566, 'James 2:7', 'James', 2, 7, 'ایا هغوی د مسیح نېک نوم چې خدای په تاسو باندې ایښی دی، نه بدناموي؟', 'ایا هغوی د مسیح نېک نوم چې خدای په تاسو باندې ایشی دی، نه بدناموی؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24567, 'James 2:8', 'James', 2, 8, 'که چېرې تاسو په رښتیا سره د څښتن د شریعت په شاهانه حکم باندې عمل وکړئ چې د خدای په کلام کې یې یادونه شوې ده چې وایي: «د خپل ګاونډي سره د خپل ځان په شان مینه کوه» نو ښه کار کوئ.', 'که چېرې تاسو په رشتیا سره د چشتن د شریعت په شاهانه حکم باندې عمل وکری چې د خدای په کلام کې یې یادونه شوې ده چې وایی: «د خپل ګاوندی سره د خپل جان په شان مینه کوه» نو شه کار کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24568, 'James 2:9', 'James', 2, 9, 'خو که چېرې تاسو د کوم چا طرفداري کوئ نو ګناه کوئ او شریعت تاسو د قانون ماتوونکو په توګه محکوموي.', 'خو که چېرې تاسو د کوم چا طرفداری کوی نو ګناه کوی او شریعت تاسو د قانون ماتوونکو په توګه محکوموی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24569, 'James 2:10', 'James', 2, 10, 'ځکه که چېرې څوک د شریعت په ټولو حکمونو عمل وکړي خو یو حکم یې مات کړي نو هغه د ټول شریعت په ماتولو ګناهکار شو.', 'جکه که چېرې چوک د شریعت په تولو حکمونو عمل وکری خو یو حکم یې مات کری نو هغه د تول شریعت په ماتولو ګناهکار شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24570, 'James 2:11', 'James', 2, 11, 'ځکه چا چې ویلي دي: «زنا مه کوه.» نو دا یې هم ویلي دي: «قتل مه کوه.» که ته زنا نه کوې خو قتل وکړې، نو بیاهم ته د شریعت ماتوونکی شوې.', 'جکه چا چې ویلی دی: «زنا مه کوه.» نو دا یې هم ویلی دی: «قتل مه کوه.» که ته زنا نه کوې خو قتل وکرې، نو بیاهم ته د شریعت ماتوونکی شوې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24571, 'James 2:12', 'James', 2, 12, 'نو د هغو خلکو په شان خبرې او عمل وکړئ چې د هغه شریعت له مخې به ورباندې قضاوت کیږي چې مونږ ته ازادي راکوي.', 'نو د هغو خلکو په شان خبرې او عمل وکری چې د هغه شریعت له مخې به ورباندې قضاوت کیزی چې مونز ته ازادی راکوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24572, 'James 2:13', 'James', 2, 13, 'ځکه چې د قضاوت په وخت کې به خدای په هغه چا باندې رحم ونه کړي چې په نورو باندې یې رحم نه دی کړی. خو بیاهم رحم په قضاوت باندې بریالی دی. بې له عمل نه ایمان مړ دی', 'جکه چې د قضاوت په وخت کې به خدای په هغه چا باندې رحم ونه کری چې په نورو باندې یې رحم نه دی کری. خو بیاهم رحم په قضاوت باندې بریالی دی. بې له عمل نه ایمان مر دی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24573, 'James 2:14', 'James', 2, 14, 'ای زما خویندو او ورونو! که څوک ووایي چې زه ایمان لرم خو عمل نه کوي نو ګټه یې څه ده؟ ایا داسې ایمان هغه ته خلاصون ورکولای شي؟', 'ای زما خویندو او ورونو! که چوک ووایی چې زه ایمان لرم خو عمل نه کوی نو ګته یې چه ده؟ ایا داسې ایمان هغه ته خلاصون ورکولای شی؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24574, 'James 2:15', 'James', 2, 15, 'فرض کړئ تاسو ووینئ چې یو ورور یا خور کالیو او خوړو ته اړتیا لري،', 'فرض کری تاسو ووینی چې یو ورور یا خور کالیو او خورو ته ارتیا لری،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24575, 'James 2:16', 'James', 2, 16, 'او ستاسو څخه یو څوک هغه ته ووایي: «په خیر لاړ شه او تود او موړ اوسه.» خو چې کومو شیانو ته اړتیا لري هغه ورته ورنه کړئ نو څه ګټه به ولري؟', 'او ستاسو چخه یو چوک هغه ته ووایی: «په خیر لار شه او تود او مور اوسه.» خو چې کومو شیانو ته ارتیا لری هغه ورته ورنه کری نو چه ګته به ولری؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24576, 'James 2:17', 'James', 2, 17, 'نو په همدې ډول که چېرې د ایمان سره عمل نه وي نو هغه ایمان مړ دی.', 'نو په همدې دول که چېرې د ایمان سره عمل نه وی نو هغه ایمان مر دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24577, 'James 2:18', 'James', 2, 18, 'خو کېدای شي چې څوک ووایي: «ته ایمان لرې او زه نېک کارونه کوم. ته دې خپل ایمان بې له عمله ماته وښایه او زه به خپل ایمان د خپلو عملونو په وسیله تاته دروښایم.»', 'خو کېدای شی چې چوک ووایی: «ته ایمان لرې او زه نېک کارونه کوم. ته دې خپل ایمان بې له عمله ماته وشایه او زه به خپل ایمان د خپلو عملونو په وسیله تاته دروشایم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24578, 'James 2:19', 'James', 2, 19, 'ته په دې باور لرې چې خدای یو دی نو ډېره ښه ده. شیطان او پېریان هم په دې باور لري او له وېرې رپیږي.', 'ته په دې باور لرې چې خدای یو دی نو دېره شه ده. شیطان او پېریان هم په دې باور لری او له وېرې رپیزی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237832, 1761237832),
(24579, 'James 2:20', 'James', 2, 20, 'ای ناپوهه سړیه! ایا په دې نه پوهېږې چې ایمان بې له عمل نه بې‌ګټې دی؟', 'ای ناپوهه سریه! ایا په دې نه پوهېزې چې ایمان بې له عمل نه بې‌ګتې دی؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_20.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
(24580, 'James 2:21', 'James', 2, 21, 'کله چې زمونږ نیکه ابراهیم خپل زوی اسحاق د قربانۍ په ځای کې خدای ته وړاندې کړ نو ایا هغه په دې عمل سره د خدای له خوا نېک ونه ګڼل شو؟', 'کله چې زمونز نیکه ابراهیم خپل زوی اسحاق د قربانی په جای کې خدای ته وراندې کر نو ایا هغه په دې عمل سره د خدای له خوا نېک ونه ګنل شو؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/James_2_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237832, 1761237832),
